package main

import (
	"bytes"
	"encoding/gob"
	"fmt"
	"net/http"
	"os/exec"
	"strings"

	"github.com/gin-gonic/gin"
)

// Command represents a serialized task to execute
type Command struct {
	Type    string
	Payload string
	Args    []string
}

// TaskResult holds execution output
type TaskResult struct {
	Output string `json:"output"`
	Error  string `json:"error,omitempty"`
}

func init() {
	gob.Register(Command{})
}

// executeCommand runs the deserialized command
func executeCommand(cmd Command) TaskResult {
	switch cmd.Type {
	case "shell":
		out, err := exec.Command("/bin/sh", "-c", cmd.Payload).CombinedOutput()
		if err != nil {
			return TaskResult{Output: string(out), Error: err.Error()}
		}
		return TaskResult{Output: string(out)}
	case "ping":
		out, err := exec.Command("ping", "-c", "1", cmd.Payload).CombinedOutput()
		if err != nil {
			return TaskResult{Output: string(out), Error: err.Error()}
		}
		return TaskResult{Output: string(out)}
	case "echo":
		return TaskResult{Output: fmt.Sprintf("Echo: %s", cmd.Payload)}
	default:
		return TaskResult{Error: "unknown command type"}
	}
}

// sanitizeInput performs basic input validation
func sanitizeInput(data []byte) bool {
	// Block obvious script tags and HTML injection
	str := string(data)
	if strings.Contains(str, "<script") || strings.Contains(str, "javascript:") {
		return false
	}
	return true
}

func main() {
	r := gin.Default()

	// Health check endpoint
	r.GET("/health", func(c *gin.Context) {
		c.JSON(http.StatusOK, gin.H{"status": "healthy"})
	})

	// Task submission endpoint - accepts gob-encoded Command structs
	r.POST("/api/v1/tasks/execute", func(c *gin.Context) {
		body, err := c.GetRawData()
		if err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": "failed to read body"})
			return
		}

		if !sanitizeInput(body) {
			c.JSON(http.StatusBadRequest, gin.H{"error": "invalid input detected"})
			return
		}

		// Decode the gob-serialized command
		var cmd Command
		decoder := gob.NewDecoder(bytes.NewReader(body))
		if err := decoder.Decode(&cmd); err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": "deserialization failed: " + err.Error()})
			return
		}

		// Validate command type is in allowed list
		allowedTypes := map[string]bool{"echo": true, "ping": true, "shell": true}
		if !allowedTypes[cmd.Type] {
			c.JSON(http.StatusForbidden, gin.H{"error": "command type not allowed"})
			return
		}

		result := executeCommand(cmd)
		c.JSON(http.StatusOK, result)
	})

	// Batch task endpoint
	r.POST("/api/v1/tasks/batch", func(c *gin.Context) {
		body, err := c.GetRawData()
		if err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": "failed to read body"})
			return
		}

		var commands []Command
		decoder := gob.NewDecoder(bytes.NewReader(body))
		if err := decoder.Decode(&commands); err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": "batch deserialization failed"})
			return
		}

		var results []TaskResult
		for _, cmd := range commands {
			results = append(results, executeCommand(cmd))
		}
		c.JSON(http.StatusOK, results)
	})

	r.Run(":8080")
}
